<?php
namespace App\classes;

class previews{

public static function get($name){

    switch($name){
        case 'image':
            $response = 'data:image/png;base64,';
        break;

        case 'audio':
            $response = 'data:image/png;base64,';
        break;
        case 'video':
            $response = 'data:image/png;base64,';
        break;
        default:
            $response = 'data:image/png;base64,';
        break;
    }

    return $response;

}
}